const ELEMENT_PROP_KEYS = new Set(["theme","word","fontWeight","hold","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  word: "Free",
  fontWeight: 500,
  hold: 46,
  fontFamily: "Albert Sans",
  scale: 1,
  delay: 0,
  speed: 1,
};

type FreeAsInElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof FreeAsInBase>;

const FreeAsInInner = forwardRef<
  HTMLDivElement,
  FreeAsInElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<FreeAsIn>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <FreeAsInBase
          {...(componentProps as unknown as ComponentProps<typeof FreeAsInBase>)}
        />
      </div>
    </Sequence>
  );
});

